def add(a, b):
    """Performs addition of two numbers."""
    return a + b

def subtract(a, b):
    """Performs subtraction of two numbers."""
    return a - b

def multiply(a, b):
    """Performs multiplication of two numbers."""
    return a * b

def divide(a, b):
    """Performs division of two numbers. Raises a ZeroDivisionError if b is zero."""
    if b == 0:
        raise ZeroDivisionError("Cannot divide by zero.")
    return a / b

def main():
    """The main part of the program that gets user input and calls the functions."""
    while True:
        try:
            # Get user input
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            operation = input("Enter the operation (+, -, *, /): ")

            # Call the corresponding function
            if operation == "+":
                result = add(num1, num2)
            elif operation == "-":
                result = subtract(num1, num2)
            elif operation == "*":
                result = multiply(num1, num2)
            elif operation == "/":
                result = divide(num1, num2)
            else:
                raise ValueError("Invalid operation. Please enter +, -, *, or /.")

            # Print the result
            print(f"{num1} {operation} {num2} = {result}")

            # Ask the user if they want to continue
            continue_input = input("Do you want to continue? (yes/no): ").lower()
            if continue_input != "yes":
                break

        except ValueError as e:
            print(e)

if __name__ == "__main__":
    main()
